using UnityEngine;
using UnityEngine.Rendering.Universal;

// Create 2D Renderer Data
var renderer2DData = ScriptableObject.CreateInstance<Renderer2DData>();
renderer2DData.name = "2D Renderer";
UnityEditor.AssetDatabase.CreateAsset(renderer2DData, "Assets/Settings/Renderer2DData.asset");

UnityEngine.Debug.Log("Created Renderer2DData.asset");

using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

// Load the 2D renderer data
var renderer2DData = UnityEditor.AssetDatabase.LoadAssetAtPath<Renderer2DData>("Assets/Settings/Renderer2DData.asset");
if (renderer2DData == null)
{
    UnityEngine.Debug.LogError("Failed to load Renderer2DData");
}
else
{
    // Create URP Asset
    var urpAsset = ScriptableObject.CreateInstance<UniversalRenderPipelineAsset>();
    urpAsset.name = "URP-2D";

    // Use reflection to set the renderer data list since there's no public API
    var rendererDataList = new ScriptableRendererData[] { renderer2DData };
    var fieldInfo = typeof(UniversalRenderPipelineAsset).GetField("m_RendererDataList", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    if (fieldInfo != null)
    {
        fieldInfo.SetValue(urpAsset, rendererDataList);
        UnityEngine.Debug.Log("Set renderer data list via reflection");
    }
    else
    {
        UnityEngine.Debug.LogError("Could not find m_RendererDataList field");
    }

    UnityEditor.AssetDatabase.CreateAsset(urpAsset, "Assets/Settings/URP-2D.asset");
    UnityEditor.AssetDatabase.SaveAssets();

    UnityEngine.Debug.Log("Created URP-2D.asset with 2D renderer");
}

