using UnityEngine;
using UnityEngine.U2D;

// Load Grass SpriteShape profile
var grassProfile = UnityEditor.AssetDatabase.LoadAssetAtPath<SpriteShapeProfile>("Assets/Flynn/SpriteShape/Grass.asset");
if (grassProfile == null)
{
    UnityEngine.Debug.LogError("Grass SpriteShape profile not found!");
}
else
{
    UnityEngine.Debug.Log($"Loaded Grass profile: {grassProfile.name}");

    // Create SpriteShape GameObject
    var groundObj = new GameObject("Ground_Grass");
    groundObj.transform.parent = null; // root level, we'll set parent after

    var ssc = groundObj.AddComponent<SpriteShapeController>();
    var ssr = groundObj.AddComponent<SpriteShapeRenderer>();

    // Configure the SpriteShapeController
    ssc.spriteShape = grassProfile;
    ssc.spline.Clear();

    // Create a wide rectangle for the ground
    // Top edge at y=0 (where sprites sit), extends down below camera view
    // Wide enough to cover camera (7.8 units) + margin
    ssc.spline.InsertPointAt(0, new Vector3(-6, 0.5f, 0));
    ssc.spline.InsertPointAt(1, new Vector3(6, 0.5f, 0));
    ssc.spline.InsertPointAt(2, new Vector3(6, -3, 0));
    ssc.spline.InsertPointAt(3, new Vector3(-6, -3, 0));

    // Make all points linear (no tangent smoothing)
    for (int i = 0; i < ssc.spline.GetPointCount(); i++)
    {
        ssc.spline.SetTangentMode(i, ShapeTangentMode.Linear);
    }

    // Close the shape
    ssc.spline.isOpenEnded = false;

    // Enable shadow casting on the renderer
    ssr.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.TwoSided;
    ssr.receiveShadows = true;

    UnityEngine.Debug.Log($"Created Ground_Grass with 4-point closed spline, shadow casting enabled");
}

