var ssc = groundObj.AddComponent<SpriteShapeController>();
var ssr = groundObj.AddComponent<SpriteShapeRenderer>();

// Configure the controller
ssc.spriteShape = grassShape;
ssc.spline.Clear();

// Create a wide rectangle: top at y=0.5, bottom at y=-3
ssc.spline.InsertPointAt(0, new Vector3(-6, 0.5f, 0));
ssc.spline.InsertPointAt(1, new Vector3(6, 0.5f, 0));
ssc.spline.InsertPointAt(2, new Vector3(6, -3, 0));
